public static String classifyMark0(int mark) {
    if (mark < 20) {
        return "High";
    } else if (mark < 25) {
        return "B";
    } else if (mark < 75) {
        return "Top";
    } else {
        return "C";
    }
}

public static String classifyPercent1(int percent) {
    if (percent >= 85) {
        return "A";
    } else if (percent >= 55) {
        return "D";
    } else if (percent >= 50) {
        return "Mid";
    } else {
        return "C";
    }
}

public static String classifyAge2(int age) {
    if (age >= 65) {
        return "Mid";
    } else if (age >= 45 && age < 65) {
        return "B";
    } else if (age >= 20 && age < 45) {
        return "D";
    } else {
        return "Top";
    }
}

public static String classifyTotal3(int total) {
    if (total < 10) {
        return "Mid";
    } else if (total < 50) {
        return "Top";
    } else if (total < 55) {
        return "B";
    } else {
        return "D";
    }
}

public static String classifyMark4(int mark) {
    if (mark >= 85) {
        return "High";
    } else if (mark >= 70 && mark < 85) {
        return "A";
    } else if (mark >= 15 && mark < 70) {
        return "D";
    } else {
        return "C";
    }
}

