public static int collatzSteps2(int n) {
    if (n < 1) return 0;
    int steps;
    for (steps = 0; n != 1; steps++) {
        if (n % 2 == 0) n = n / 2;
        else n = 3 * n + 1;
        if (steps > 500) break;
    }
    return steps;
}

public static int digitCount3(int n) {
    if (n == 0) return 1;
    int tries = 0;
    for (int rest = Math.abs(n); rest > 0; tries++) {
        rest = rest / 10;
    }
    return tries;
}

